examples.template:
MonarchAiUndoBanner(
    {{title}},
    changes: [
        MonarchAiChange({{changes.0.label}}, before: {{changes.0.before}}, after: {{changes.0.after}}),
        MonarchAiChange({{changes.1.label}}, before: {{changes.1.before}}, after: {{changes.1.after}}),
        MonarchAiChange({{changes.2.label}}, before: {{changes.2.before}}, after: {{changes.2.after}}),
    ],
    auditURL: URL(string: "https://app.example.com/audit/812"),
    onUndo: {}
)

examples.code:
MonarchAiUndoBanner(
    "AI changed 3 fields",
    changes: [
        MonarchAiChange("Status", before: "Open", after: "In progress"),
        MonarchAiChange("Owner", before: "Unassigned", after: "Sam Lee"),
        MonarchAiChange("Priority", before: "Normal", after: "High"),
    ],
    auditURL: URL(string: "https://app.example.com/audit/812"),
    onUndo: {}
)

if isShown {
    MonarchAiUndoBanner(
        "AI archived 12 tickets",
        duration: .seconds(30),
        onUndo: {},
        onDismiss: { isShown = false }
    )
}
